// EditAboutForm.js
import React, { useState } from 'react';
import axios from 'axios';

const EditAbout = () => {
    const [aboutContent, setAboutContent] = useState({title : '', description : ''});


    const handleFormSubmit = async (aboutData) => {
        try {
          const response = await axios.post("http://localhost:5000/about", aboutData);
          console.log("✅ About section updated:", response.data.message);
          alert("About section updated successfully!");
        } catch (error) {
          console.error("❌ Error updating about section:", error);
          alert("Error updating about section.");
        }
      };


    return (
        <div className='Edit'>
            <div className='Con' >
            <h2>Edit About </h2>
            <form onSubmit={handleFormSubmit}>
            <input
                    value={aboutContent.title}
                    onChange={(e) => setAboutContent(e.target.value)}
                    placeholder="Enter new about title section content"
             />
                <textarea
                    value={aboutContent.description}
                    onChange={(e) => setAboutContent(e.target.value)}
                    placeholder="Enter new about description section content"
                />
                <button type="submit">Save</button>
            </form>
            </div>
        </div>
    );
};

export default EditAbout;
